<?php // Media and document archive interface; uploads need server-side validation and storage. ?>
<style>
.doc-card{background:#fff;border:1px solid #e3e8ef;border-radius:14px;padding:22px}.doc-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:15px}.doc-field{display:flex;flex-direction:column;gap:7px}.doc-field.wide{grid-column:1/-1}.doc-field label{font-size:12px;font-weight:700;color:#34465c}.doc-field input,.doc-field select,.doc-field textarea{width:100%;min-height:42px;padding:10px;border:1px solid #d9e1eb;border-radius:8px;font:inherit;font-size:12px}.doc-btn{border:0;border-radius:8px;padding:11px 16px;background:#2463a6;color:#fff;font:inherit;font-size:12px;cursor:pointer}.doc-note{padding:11px 14px;margin-bottom:15px;background:#fff8e7;border:1px solid #f1dfb2;border-radius:9px;color:#77551a;font-size:12px;line-height:1.8}@media(max-width:560px){.doc-grid{grid-template-columns:1fr}.doc-field.wide{grid-column:auto}.doc-card{padding:15px}}
</style>
<div class="doc-note">برای امنیت، فایل‌ها باید هنگام پیاده‌سازی سمت سرور بررسی شوند: نوع و حجم فایل، نام تصادفی، دسترسی مجاز و جلوگیری از اجرای فایل‌های آپلودشده. این فورم هنوز فایل را آپلود یا ذخیره نمی‌کند.</div>
<form class="doc-card" id="documentsForm"><h2 style="font-size:16px;margin:0 0 18px">ثبت تصویر یا سند ملک</h2><div class="doc-grid">
<div class="doc-field"><label>کد ملک</label><input name="property_code" required></div><div class="doc-field"><label>نوع فایل</label><select name="document_type"><option>تصویر ملک</option><option>سند مالکیت</option><option>نقشه ساختمان</option><option>قرارداد</option><option>مدرک هویتی مجاز</option><option>سایر</option></select></div>
<div class="doc-field wide"><label>انتخاب فایل</label><input type="file" name="files[]" multiple accept="image/jpeg,image/png,image/webp,application/pdf"></div><div class="doc-field wide"><label>توضیحات</label><textarea name="description"></textarea></div>
</div><div style="margin-top:18px"><button class="doc-btn" type="submit">ثبت فایل‌ها</button></div><p id="documentsMessage" role="status" style="font-size:12px;line-height:1.8"></p></form>
<script>(function(){const f=document.getElementById('documentsForm'),m=document.getElementById('documentsMessage');f.addEventListener('submit',e=>{e.preventDefault();m.textContent='فایل انتخاب شد، اما بارگذاری امن و ذخیره‌سازی سمت سرور هنوز پیاده‌سازی نشده است.';m.style.color='#77551a';});})();</script>